// Normalize lead payloads from website forms, Facebook Lead Ads, Typeform, Jotform, generic.
const b = $json.body || {};
const q = $json.query || {};
const pick = (...keys) => { for (const k of keys) { if (b[k] !== undefined && b[k] !== null && String(b[k]).trim() !== '') return String(b[k]).trim(); } return ''; };
let name = pick('name','full_name','fullName','Name');
const first = pick('first_name','firstName');
const last = pick('last_name','lastName');
if (!name && (first || last)) name = `${first} ${last}`.trim();
let phone = pick('phone','phone_number','phoneNumber','Phone','mobile');
// Basic E.164 normalization for US (10-digit -> +1). Adjust per locale.
const digits = phone.replace(/[^0-9]/g, '');
if (digits.length === 10) phone = '+1' + digits;
else if (digits.length === 11 && digits.startsWith('1')) phone = '+' + digits;
else if (phone && !phone.startsWith('+')) phone = '+' + digits;
const email = pick('email','Email','email_address');
const service = pick('service','service_needed','subject','interest','topic');
const message = pick('message','notes','comments','inquiry','details','description');
const source = pick('source','utm_source') || q.source || 'Website Form';
return [{ json: { name, phone, email, service, message, source, received_at: $now.toISO() } }];

